<script setup lang="ts">
import {computed} from 'vue';
import {NButton} from 'naive-ui';import {EMPLOYEE_AVATAR_PRESETS,PORTRAIT_EMPLOYEE_AVATAR_PRESETS,LEGACY_EMPLOYEE_AVATAR_PRESETS,resolveEmployeeAvatarPreset} from '@dentity/contracts';import EmployeeAvatar from './EmployeeAvatar.vue';
const props=defineProps<{creation?:boolean;disabled?:boolean;identityKey?:string}>();const value=defineModel<string|null>('value',{required:true});
const options=[...PORTRAIT_EMPLOYEE_AVATAR_PRESETS,...LEGACY_EMPLOYEE_AVATAR_PRESETS];
const displayed=computed(()=>resolveEmployeeAvatarPreset(value.value,props.identityKey??''));
const quickOptions=computed(()=>[displayed.value,...PORTRAIT_EMPLOYEE_AVATAR_PRESETS.filter(p=>p!==displayed.value)].slice(0,3));
function random(){const rest=PORTRAIT_EMPLOYEE_AVATAR_PRESETS.filter(v=>v!==displayed.value);value.value=rest[Math.floor(Math.random()*rest.length)]!;}
</script>
<template><fieldset class="avatar-picker" :class="{'avatar-picker-creation':creation}" :disabled="disabled"><legend v-if="!creation">员工头像</legend><div class="avatar-current"><EmployeeAvatar name="" :preset="displayed"/><NButton v-if="!creation" :disabled="disabled" @click="random">换一个</NButton></div><div v-if="creation" class="avatar-quick-presets" aria-label="预设头像"><NButton v-for="preset in quickOptions" :key="preset" :disabled="disabled" :aria-label="`选择头像 ${EMPLOYEE_AVATAR_PRESETS.indexOf(preset)+1}`" :aria-pressed="displayed===preset" :class="{'avatar-selected':displayed===preset}" @click="value=preset"><EmployeeAvatar name="" :preset="preset"/></NButton></div><details class="avatar-choice"><summary>{{creation?'选择预设头像':'选择头像'}}</summary><div class="avatar-presets"><NButton v-for="preset in options" :key="preset" :disabled="disabled" :aria-label="`选择头像 ${EMPLOYEE_AVATAR_PRESETS.indexOf(preset)+1}`" :aria-pressed="displayed===preset" :class="{'avatar-selected':displayed===preset}" @click="value=preset"><EmployeeAvatar name="" :preset="preset"/><span v-if="displayed===preset" class="avatar-check" aria-hidden="true">✓</span></NButton></div></details></fieldset></template>
